[ExtensionOf(formControlStr(AVASCPProdBOMVendorListPage, AVASubcontractorOrderPrintMail))]
final class AVAAVASCPProdBOMVendorListPageFrm_AVASubcontractorOrderPrintMail_Extension
{
}

Method.Source:
/// <summary>
/// clicked method
/// </summary>
public void clicked()
{

    FormControl curButton = any2Object(this) as FormControl;
    FormDataSource          avaProdBomVendorTmpFds = curButton.formRun().dataSource(tableStr(AVASCPProdBOMVendorTmp));
    AVASCPProdBOMVendorTmp  avaProdBomVendorTmp;
    PurchTable              avaPurchTable;

    if (avaProdBomVendorTmpFds)
    {
        avaProdBomVendorTmp.data(avaProdBomVendorTmpFds.cursor());
        avaPurchTable = PurchTable::find(avaProdBomVendorTmp.PurchId);
    }
    if (avaPurchTable.Email == '')
    {
        throw Error("@NDX:NXAEmailInPurchOrderMiss");
    }

    next clicked();

    if (avaPurchTable)
    {
        Args args = new Args();

        args.record(avaPurchTable);
        args.caller(curButton);

        new MenuFunction(menuItemOutputStr(AVASubcontractorOrderPrintMail), MenuItemType::Output).run(args);
    }

}
